from __future__ import annotations

from typing import Any

from comment_store import CommentStore


def create_comment(payload: dict[str, Any], store: CommentStore) -> dict[str, Any]:
    post_id = str(payload.get("post_id", "")).strip()
    author = str(payload.get("author", "")).strip()
    message = str(payload.get("message", ""))

    if not post_id:
        return {"ok": False, "reason": "invalid_post_id"}
    if not author:
        return {"ok": False, "reason": "invalid_author"}
    if not message.strip():
        return {"ok": False, "reason": "invalid_message"}

    record = {
        "id": store.count() + 1,
        "post_id": post_id,
        "author": author,
        "message": message,
    }
    store.add(record)
    return {"ok": True, "reason": "created", "comment": record}


def render_comments_html(post_id: str, store: CommentStore) -> dict[str, Any]:
    comments = store.list_for_post(post_id)
    parts: list[str] = []
    for item in comments:
        # Bug: message rendered directly into HTML.
        parts.append(
            "<li>"
            + "<strong>" + item["author"] + "</strong>: "
            + item["message"]
            + "</li>"
        )
    html = "<ul>" + "".join(parts) + "</ul>"
    return {"ok": True, "reason": "ok", "html": html, "count": len(comments)}


def create_and_render(payload: dict[str, Any], store: CommentStore) -> dict[str, Any]:
    created = create_comment(payload, store)
    if not created.get("ok"):
        return created
    rendered = render_comments_html(str(payload.get("post_id", "")), store)
    return {"ok": True, "reason": "ok", "created": created["comment"], "html": rendered["html"]}

