from __future__ import annotations

from typing import Any


class CommentStore:
    def __init__(self) -> None:
        self._comments: list[dict[str, Any]] = []

    def add(self, comment: dict[str, Any]) -> None:
        self._comments.append(
            {
                "id": int(comment.get("id", len(self._comments) + 1)),
                "author": str(comment.get("author", "")).strip(),
                "message": str(comment.get("message", "")),
                "post_id": str(comment.get("post_id", "")).strip(),
            }
        )

    def list_for_post(self, post_id: str) -> list[dict[str, Any]]:
        pid = post_id.strip()
        if not pid:
            return []
        return [dict(item) for item in self._comments if str(item.get("post_id", "")) == pid]

    def count(self) -> int:
        return len(self._comments)

    def clear(self) -> None:
        self._comments.clear()

    def snapshot(self) -> list[dict[str, Any]]:
        return [dict(item) for item in self._comments]

    def has_post(self, post_id: str) -> bool:
        return len(self.list_for_post(post_id)) > 0

    def latest_for_post(self, post_id: str) -> dict[str, Any] | None:
        items = self.list_for_post(post_id)
        if not items:
            return None
        return items[-1]

    def remove(self, comment_id: int) -> bool:
        before = len(self._comments)
        self._comments = [item for item in self._comments if int(item.get("id", -1)) != int(comment_id)]
        return len(self._comments) != before

    def ids_for_post(self, post_id: str) -> list[int]:
        return [int(item.get("id", 0)) for item in self.list_for_post(post_id)]

    def author_count(self, author: str) -> int:
        key = author.strip().lower()
        if not key:
            return 0
        return len([item for item in self._comments if str(item.get("author", "")).strip().lower() == key])

